-- ============================================================================
-- PARTIE 26 — Version e-learning du module 1 : séquence pilote 1/3 (Apport)
-- Source : support « Le paradoxe de l'accueil collectif » (séparation et
-- attachement sécure), partie 13 et partie 23 du module 1, et le module
-- « Le port d'attache » du thème « L'attachement » (Bowlby, Ainsworth).
-- Crée un second thème, en parallèle de la séance animée de 45 min, avec une
-- séquence en lecture seule d'environ 30 minutes : 43 blocs dont 6 questions avec
-- correction, 3 mises en situation et 3 temps de réflexion.
-- LA SÉQUENCE RESTE EN BROUILLON (publie = false).
-- Prérequis : partie 25 exécutée (types « question » et « dialogue »), et
-- dossier images/module1/ déployé avec l'application (dont prendre-soin.jpg).
-- À exécuter en 3 temps : 26.1, 26.2, puis 26c.
-- Relançable : le thème et la séquence ne sont créés qu'une fois, et les blocs
-- ne sont ajoutés que si la séquence n'en contient aucun.
-- Les prénoms (Enzo, Julia, Camille, Sacha, Maëlle, Tom) sont ceux de vignettes
-- et d'exemples, pas d'enfants du site.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 26.1 Thème et séquence. Attendu : aucune ligne retournée.
-- ---------------------------------------------------------------------------
do $do$
declare tid public.theme.id%type;
begin
  select id into tid from public.theme where nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$;
  if tid is null then
    insert into public.theme(nom, description, ordre, programme)
    values ($kk$Module 1 – Développement et attachement (e-learning)$kk$,
            $kk$Version e-learning du module 1, à suivre à son rythme : lecture, situations vécues, questions avec correction et mises en situation. 3 séquences d'environ 30 minutes. Complète les microséquences animées de 45 min.$kk$,
            0, 'Programme de formation (Modules 1 à 10)')
    returning id into tid;
  end if;

  if not exists (select 1 from public.module where theme_id = tid and titre = $kk$Module 1 – 1/3 · Apport (e-learning)$kk$) then
    insert into public.module(theme_id, titre, accroche, publie, ordre, trame)
    values (tid, $kk$Module 1 – 1/3 · Apport (e-learning)$kk$,
            $kk$Enzo, 9 mois, entre pour la première fois dans la section des bébés. Son regard se pose sur vous : il se fige, puis il pleure. **Que dit ce regard, et comment devenir une base sûre pour lui et pour ses parents ?**$kk$,
            false, 0, null);
  end if;
end
$do$;
-- FIN 26.1

-- ---------------------------------------------------------------------------
-- 26.2 Blocs de la séquence. Attendu : aucune ligne retournée (blocs ajoutés une seule fois).
-- ---------------------------------------------------------------------------
do $do$
declare mid public.module.id%type;
begin
  select m.id into mid from public.module m join public.theme t on t.id = m.theme_id
  where t.nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$ and m.titre = $kk$Module 1 – 1/3 · Apport (e-learning)$kk$;
  if mid is null then raise notice '26.2 : séquence introuvable, exécuter 26.1'; return; end if;
  if exists (select 1 from public.bloc where module_id = mid) then raise notice '26.2 : déjà exécuté'; return; end if;

  insert into public.bloc(module_id, type, contenu, ordre)
  select mid, v.type, v.contenu, v.ordre
  from (values
  ('texte', $kk${"titre": "Ce que vous allez faire", "paragraphes": ["Cette séquence est la version à suivre **à votre rythme** de la première séance du module 1. Comptez **environ 30 minutes**, en une fois ou en deux temps : vous pouvez vous arrêter et reprendre quand vous le souhaitez.", "Vous y trouverez des repères, des situations vécues, **six questions avec correction** et **trois mises en situation** à compléter. Les questions ne sont pas notées : elles servent à apprendre. Ce que vous écrivez reste sur votre appareil.", "À la fin, vous saurez expliquer pourquoi la séparation est une épreuve pour un jeune enfant, reconnaître si un enfant s'appuie déjà sur une base sûre ou cherche encore à se sécuriser, et choisir des gestes et des mots qui apaisent, pour l'enfant comme pour son parent."]}$kk$::jsonb, 0),
  ('image', $kk${"url": "images/module1/accueil-collectif.jpg", "alt": "Deux mains qui se rejoignent entre deux motifs colorés", "legende": "Accueillir, c'est d'abord séparer : l'enfant quitte ses premières figures d'attachement pour entrer dans un collectif."}$kk$::jsonb, 1),
  ('texte', $kk${"titre": "Accueillir, c'est d'abord séparer", "paragraphes": ["Par définition, l'accueil en collectivité introduit **une séparation** d'avec les premières figures d'attachement, le plus souvent les parents. L'enfant entre dans un lieu où il ne connaît encore ni les adultes, ni les autres enfants, ni les rythmes. C'est une expérience qui touche aux fondements de la relation parent-enfant.", "Ce constat n'a rien de culpabilisant pour les familles ni pour les équipes. Il pose une exigence : mettre en place des **conditions d'accueil qui n'entravent pas le développement de l'enfant, mais l'accompagnent**. C'est tout l'enjeu de ce module."]}$kk$::jsonb, 2),
  ('citation', $kk${"texte": "« Il est nécessaire de rappeler que la vie en dehors de son milieu familial et la vie collective n'est pas un besoin pour le tout petit. Il s'agit donc de mettre en place des conditions d'accueil qui n'entravent pas son développement mais au contraire l'accompagne… »\nMiriam Rasse"}$kk$::jsonb, 3),
  ('reflexion', $kk${"question": "Repensez à la dernière arrivée d'un enfant dans votre section. Qu'avez-vous vu : son regard, son corps, ses pleurs, son parent ? Et qu'avez-vous ressenti vous-même ?", "sous_titre": "Il s'agit de décrire, pas de juger. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 4),
  ('texte', $kk${"titre": "Le monde à travers les yeux d'un enfant", "paragraphes": ["Pour comprendre ce qui se joue, placez-vous du côté de l'enfant. Voici deux situations, à deux âges différents. Lisez-les d'abord comme si vous étiez l'enfant, puis comme professionnelle."]}$kk$::jsonb, 5),
  ('image', $kk${"url": "images/module1/enzo.jpg", "alt": "Un bébé aux grands yeux, accroché à l'épaule de sa maman", "legende": "Enzo, 9 mois : son regard attentif, son accrochage et ses pleurs disent sa peur."}$kk$::jsonb, 6),
  ('image', $kk${"url": "images/module1/julia.jpg", "alt": "Silhouette d'un tout-petit à quatre pattes au milieu de traits rouges et noirs agités", "legende": "Julia, 20 mois : une tempête intérieure qu'elle ne peut ni nommer, ni réguler seule."}$kk$::jsonb, 7),
  ('scenes', $kk${"titre": "Enzo et Julia : ce que dit leur réaction", "items": [{"lettre": "A", "titre": "Enzo, 9 mois, se fige puis pleure", "texte": "Enzo entre pour la première fois dans la section des bébés. Il balaie la pièce du regard, s'accroche aux bras de sa maman et, dès que son regard se pose sur un adulte inconnu, il se fige puis se met à pleurer.", "analyse": "ce n'est pas un caprice. Son système d'attachement s'active face à ce qu'il perçoit comme un danger : son regard attentif, son accrochage et ses pleurs disent sa peur et son besoin de protection."}, {"lettre": "B", "titre": "Julia, 20 mois, se jette par terre", "texte": "Le visage de Julia se fige quand sa mère annonce son départ. Elle s'accroche à ses jambes, puis se jette par terre quand elle disparaît. À plat ventre, elle crie, tape des pieds et des mains sur le sol.", "analyse": "elle proteste contre l'angoisse de perte. Elle est débordée : son corps exprime une colère et une frustration qu'elle ne peut ni nommer, ni réguler seule."}]}$kk$::jsonb, 8),
  ('question', $kk${"enonce": "Enzo se fige puis pleure quand son regard se pose sur un adulte inconnu. Que **traduit** le plus justement sa réaction ?", "options": [{"texte": "Un caprice qu'il ne faut pas encourager", "juste": false}, {"texte": "L'activation de son système d'attachement face à ce qu'il perçoit comme un danger", "juste": true}, {"texte": "Un manque d'habitude du collectif, qui disparaîtra en le laissant pleurer", "juste": false}], "explication": "Sa réaction n'est pas un caprice : c'est un message. Son regard attentif, son accrochage et ses pleurs expriment un **besoin primaire de protection**."}$kk$::jsonb, 9),
  ('question', $kk${"enonce": "Julia se jette par terre quand sa mère disparaît. Quelle lecture est la plus juste ?", "options": [{"texte": "Elle cherche à manipuler sa mère pour qu'elle reste", "juste": false}, {"texte": "Elle proteste contre l'angoisse de perte, et elle est débordée par des émotions qu'elle ne peut pas réguler seule", "juste": true}, {"texte": "Elle est en colère contre la professionnelle", "juste": false}], "explication": "Julia est **débordée** : son corps exprime une colère et une frustration qu'elle ne peut ni nommer, ni calmer seule. Cette protestation est normale à cet âge."}$kk$::jsonb, 10),
  ('texte', $kk${"titre": "Un cerveau en construction", "paragraphes": ["Les neurosciences affectives le confirment : le cerveau du jeune enfant est **profondément immature**. Deux zones jouent un rôle clé. Le **cerveau émotionnel** (notamment l'amygdale) est hyperactif et domine : l'enfant ressent toutes les émotions à l'état brut. Le **cortex préfrontal**, le « régulateur », est encore en développement : il ne peut pas calmer les impulsions, prendre du recul ou analyser la situation.", "La conséquence est lourde de sens : **l'enfant ne PEUT PAS contrôler ses émotions**. Ce n'est ni un caprice, ni une provocation. Il a, neurologiquement, besoin d'un adulte « **co-régulateur** », c'est-à-dire d'un adulte qui l'aide à se calmer.", "Quand un enfant « craque », la question utile n'est donc pas « comment l'arrêter ? » mais « **comment l'aider à retrouver son calme ?** »."]}$kk$::jsonb, 11),
  ('image', $kk${"url": "images/module1/cerveau.jpg", "alt": "Schéma d'un cerveau immature, où l'amygdale domine, et d'un cerveau mature, où le cortex préfrontal régule", "legende": "À gauche, un cerveau immature : le centre émotionnel de la peur domine, le régulateur est en développement. À droite, un cerveau mature : le régulateur est fonctionnel."}$kk$::jsonb, 12),
  ('question', $kk${"enonce": "Parmi ces affirmations sur le cerveau du jeune enfant, lesquelles sont justes ? (plusieurs réponses)", "options": [{"texte": "Le cerveau émotionnel domine : l'enfant ressent ses émotions à l'état brut", "juste": true}, {"texte": "Le cortex préfrontal, qui régule les émotions, est encore en développement", "juste": true}, {"texte": "Un enfant qui hurle cherche surtout à provoquer l'adulte", "juste": false}, {"texte": "Il a besoin d'un adulte qui l'aide à se calmer", "juste": true}], "explication": "Un jeune enfant **ne peut pas** réguler seul l'intensité de ses émotions. Hurler n'est pas une provocation : c'est un débordement. L'adulte est son « co-régulateur »."}$kk$::jsonb, 13),
  ('texte', $kk${"titre": "Le besoin d'attachement, fondement de la sécurité intérieure", "paragraphes": ["Le psychiatre britannique **John Bowlby** (à partir des années 1950) a proposé que l'attachement est un **besoin social primaire**, aussi vital que manger ou dormir. Le jeune enfant est orienté vers la recherche de proximité avec une **figure d'attachement** : la personne vers qui il se tourne préférentiellement pour trouver proximité et sécurité, et dont la séparation provoque une protestation.", "Quand l'enfant peut compter sur un adulte sensible, il intériorise cette relation sécurisante : c'est sa **base de sécurité**. **Mary Ainsworth**, collaboratrice de Bowlby, a montré que les enfants s'éloignent de cette base pour explorer, y reviennent quand ils sont inquiets, puis repartent rassurés. On parle de **havre de sécurité** (revenir se réfugier quand on est troublé) et de base de sécurité (partir explorer en sachant qu'on peut revenir). C'est ce que nous appelons le **port d'attache**.", "D'où un **paradoxe** : pour devenir autonome et capable d'être seul, l'enfant doit d'abord avoir fait l'expérience d'une **dépendance sécurisante**. Plus il se sent soutenu, plus il ose s'éloigner."]}$kk$::jsonb, 14),
  ('image', $kk${"url": "images/module1/base-securite.jpg", "alt": "Un adulte penché vers un enfant, reliés par un fil lumineux", "legende": "La base de sécurité : c'est parce qu'il a connu une dépendance sécurisante que l'enfant devient capable d'explorer et d'être seul."}$kk$::jsonb, 15),
  ('citation', $kk${"texte": "« Un bébé (tout seul) cela n'existe pas. Il fait essentiellement partie d'une relation. »\nD. W. Winnicott"}$kk$::jsonb, 16),
  ('texte', $kk${"titre": "Sécure, insécure : où en est chaque enfant ?", "paragraphes": ["Les enfants ne sont pas tous au même point. Un attachement dit **« sécure »** permet à l'enfant de se sécuriser même en l'absence de l'adulte. Un attachement dit **« insécure »** ne le permet pas encore : toute son énergie va à la recherche de sécurisation, et il n'est pas disponible pour jouer.", "Ces mots décrivent **où en est l'enfant dans sa relation**, pas ce qu'il est : on n'étiquette pas un enfant. Savoir où il en est permet d'**adapter notre accompagnement**, et la sécurité affective vient toujours avant l'exploration.", "Un repère utile : pleurer au moment de la séparation ne dit pas, à lui seul, qu'un enfant est insécure. Ce qui compte, c'est ce qui se passe ensuite : l'enfant peut-il être consolé, puis repartir jouer ?"]}$kk$::jsonb, 17),
  ('scenes', $kk${"titre": "Trois enfants, trois façons de s'appuyer sur l'adulte", "items": [{"lettre": "A", "titre": "Il explore et revient jeter un coup d'œil", "texte": "Sacha, 18 mois, joue dans le coin des voitures. De temps en temps, il lève la tête, croise le regard de l'adulte assise non loin, puis repart.", "analyse": "il s'appuie déjà sur une base sûre. Il sait qu'il peut revenir, donc il ose s'éloigner. L'adulte reste visible et disponible."}, {"lettre": "B", "titre": "Elle ne joue que si elle touche l'adulte", "texte": "Maëlle, 14 mois, ne quitte pas l'adulte des yeux. Elle ne joue que si elle est contre lui, et pleure dès qu'il se lève.", "analyse": "elle cherche encore à se sécuriser. Son énergie est tournée vers la sécurité, pas vers le jeu. On lui offre un ou deux adultes stables et disponibles, sans multiplier les changements."}, {"lettre": "C", "titre": "Il pleure au départ de son père, puis se laisse consoler", "texte": "Tom, 2 ans, pleure quand son père s'en va. Une adulte le prend dans les bras, lui parle. Au bout de quelques minutes, il se calme et rejoint les jeux.", "analyse": "ses pleurs sont normaux : il protestait contre la séparation. L'important est qu'il ait pu être consolé, puis repartir. L'adulte a joué son rôle de port d'attache."}]}$kk$::jsonb, 18),
  ('question', $kk${"enonce": "Maëlle (14 mois) ne joue que si elle touche l'adulte. Quelle réponse de l'équipe est la plus adaptée ?", "options": [{"texte": "L'encourager à jouer seule : elle doit apprendre l'autonomie", "juste": false}, {"texte": "Lui offrir un adulte stable et disponible, jusqu'à ce qu'elle se sente assez en sécurité pour jouer", "juste": true}, {"texte": "Changer souvent d'adulte autour d'elle pour qu'elle s'habitue à tous", "juste": false}, {"texte": "Lui donner systématiquement son doudou à la place de l'adulte", "juste": false}], "explication": "Un enfant insécurisé n'est pas disponible pour jouer. Il faut d'abord lui offrir une **base stable**. On évite de changer souvent d'adulte, et un doudou proposé systématiquement finit par prendre la place de l'adulte, qui reste la figure d'attachement."}$kk$::jsonb, 19),
  ('reflexion', $kk${"question": "Pour un enfant de votre section, qui est sa base sûre ? Où le voyez-vous revenir vers cet adulte, et dans quels moments de la journée n'a-t-il pas de repère ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 20),
  ('texte', $kk${"titre": "Les émotions se construisent à deux", "paragraphes": ["Un enfant n'apprend pas seul à gérer ses émotions : il l'apprend **dans la relation**, par étapes. De 0 à 3 mois, le bébé exprime ses émotions à l'état brut : l'adulte est un co-régulateur externe indispensable, qui décode, nomme et apaise. De 3 à 24 mois, grâce au « mirroring » de l'adulte, le bébé apprend à nuancer ses expressions et découvre la valeur communicative de ses émotions. De 2 à 6 ans, l'enfant commence à intérioriser les stratégies de l'adulte, en utilisant le jeu et le langage pour « rejouer » et comprendre ses émotions.", "Le développement émotionnel n'est pas automatique : il est « **modelé** » par la qualité des réponses et de l'expressivité des personnes qui prennent soin de l'enfant."]}$kk$::jsonb, 21),
  ('image', $kk${"url": "images/module1/competences-emotionnelles.jpg", "alt": "Trois étapes du développement émotionnel : de 0 à 3 mois, de 3 à 24 mois, de 2 à 6 ans", "legende": "Co-régulateur externe, puis miroir des émotions, jusqu'à la régulation par l'enfant lui-même : un dialogue permanent avec l'adulte."}$kk$::jsonb, 22),
  ('texte', $kk${"titre": "Face à la tempête : de la réaction à la co-régulation", "paragraphes": ["Face à une « tempête émotionnelle », la réaction de l'adulte est déterminante. Elle peut apaiser et construire, ou au contraire renforcer l'insécurité.", "Une réaction **soutenante** accueille l'émotion sans jugement, la nomme, réconforte et aide à trouver des stratégies : l'enfant apprend à se réguler, son cortex orbito-frontal mature et son estime de lui se renforce. Une réaction **non soutenante** nie, minimise, punit ou isole : l'enfant apprend à refouler ses émotions, son anxiété augmente et le développement de sa régulation est entravé."]}$kk$::jsonb, 23),
  ('image', $kk${"url": "images/module1/reactions-adulte.jpg", "alt": "Deux cerveaux : réactions soutenantes de l'adulte et réactions non soutenantes, avec leur impact", "legende": "Face à une tempête émotionnelle, la réaction de l'adulte apaise et construit, ou renforce l'insécurité."}$kk$::jsonb, 24),
  ('comparaison', $kk${"intro": "**Quand un enfant est submergé par ses émotions.**", "plutot": ["Accueillir l'émotion sans jugement : « Tu as le droit d'être en colère. »", "La nommer.", "Réconforter, puis aider à trouver des stratégies."], "eviter": ["Nier ou minimiser : « Ce n'est rien. »", "Punir.", "Isoler l'enfant."]}$kk$::jsonb, 25),
  ('question', $kk${"enonce": "« Consoler un enfant qui pleure, c'est du laxisme. » Que répondez-vous ?", "options": [{"texte": "C'est vrai : il doit apprendre à se calmer seul", "juste": false}, {"texte": "C'est faux : consoler, c'est participer activement à la maturation de son cerveau", "juste": true}, {"texte": "C'est vrai, sauf pour les bébés de moins de 3 mois", "juste": false}], "explication": "Consoler n'est pas du laxisme : c'est **aider le cerveau de l'enfant à mûrir**. Un enfant consolé apprend à se réguler ; un enfant isolé ou dont on nie l'émotion apprend à la refouler."}$kk$::jsonb, 26),
  ('texte', $kk${"titre": "Confier son enfant : ce que vivent les parents", "paragraphes": ["La séparation n'est pas seulement l'épreuve de l'enfant. Pour les parents, confier son enfant est une expérience chargée d'émotions complexes. **La culpabilité** : le sentiment d'aller à l'encontre de l'instinct de protection. **L'anxiété et la peur** : la crainte de perdre l'amour de son enfant, de se sentir « dépossédé ». **La fragilisation** : le sentiment de compétence parentale est mis à l'épreuve, surtout face aux pleurs.", "Un point de vigilance : **les angoisses parentales se communiquent à l'enfant**. Un parent stressé amplifie l'angoisse de son enfant. Accueillir l'enfant, c'est donc aussi **accueillir son parent**."]}$kk$::jsonb, 27),
  ('image', $kk${"url": "images/module1/parents.jpg", "alt": "Silhouette d'un parent dont la poitrine est occupée par un nœud de fils, un petit enfant à distance", "legende": "Confier son enfant est une épreuve : les angoisses du parent se communiquent à l'enfant."}$kk$::jsonb, 28),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Un parent hésite à partir", "contexte": "8 h 30. Camille, 11 mois, vient d'arriver. Elle pleure dans les bras de son père, qui est resté sur le seuil de la section.", "repliques": [{"qui": "Le papa de Camille", "texte": "Elle pleure à chaque fois que je pars. Je me sens horrible, j'ai l'impression de l'abandonner. Je crois que je vais rester encore un peu."}], "consigne": "Que répondez-vous à ce parent ?", "reponse_modele": "Je comprends que ce soit difficile pour vous. Ses pleurs disent qu'elle tient à vous, ce n'est pas un échec de votre part. Dites-lui au revoir à votre manière, puis je prends le relais : je reste près d'elle et je la console. Je vous donnerai de ses nouvelles dans la matinée.", "points": ["Accueillir l'émotion du parent sans jugement, sans minimiser (« ce n'est rien »).", "Dire ce que vous allez faire : prendre le relais et consoler.", "Reconnaître que le rituel de séparation appartient à la famille.", "Proposer un temps de nouvelles : la qualité des transmissions rassure."]}$kk$::jsonb, 29),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "« Elle ne veut plus que vous »", "contexte": "17 h. Une maman vient chercher sa fille de 15 mois, qui court vers vous avec le sourire.", "repliques": [{"qui": "La maman", "texte": "Elle ne veut plus que vous, maintenant ! J'ai peur qu'elle s'attache plus à vous qu'à moi."}], "consigne": "Que répondez-vous à cette maman ?", "reponse_modele": "Je comprends cette crainte. Votre place ne change pas : vous êtes son point d'origine et son port d'attache. Elle s'attache aussi à nous, mais cela ne remplace pas ce qu'elle vit avec vous, cela le complète. Si elle se sent en sécurité ici, c'est justement grâce à ce que vous avez construit avec elle.", "points": ["Nommer la peur d'être « dépossédé » plutôt que la nier.", "Rappeler que l'attachement à la crèche complète celui avec les parents, il ne le remplace pas.", "Reconnaître l'expertise des parents : ils sont les premiers éducateurs de leur enfant."]}$kk$::jsonb, 30),
  ('texte', $kk${"titre": "Tisser des fils de continuité entre la maison et la crèche", "paragraphes": ["Face à l'immaturité de l'enfant et à l'anxiété des parents, le professionnel a un rôle pivot. Il ne s'agit pas simplement de « garder » : il s'agit de **construire** un environnement qui préserve le « sentiment de continuité d'être » de l'enfant. Pour un jeune enfant, la **discontinuité** (des lieux, des personnes, des rythmes) peut faire obstacle au sentiment de sécurité intérieure.", "Trois fils sont à tisser. **Une figure de sécurité de substitution** : un adulte stable, permanent et disponible, que l'enfant investit. **La continuité relationnelle** : des interactions prévisibles, fiables et chaleureuses, particulièrement durant les soins. **La continuité de l'environnement** : un cadre de vie stable, avec des repères, des rituels et des règles cohérentes.", "En pratique, cela passe par la **période de familiarisation**, la **qualité des transmissions** et le respect de l'**objet transitionnel**."]}$kk$::jsonb, 31),
  ('image', $kk${"url": "images/module1/pont-maison-creche.jpg", "alt": "Un pont entre une maison et une crèche, traversé par des enfants, au-dessus d'une poignée de main", "legende": "Le professionnel est un pont entre la maison et la crèche : il construit le « sentiment de continuité d'être » de l'enfant."}$kk$::jsonb, 32),
  ('image', $kk${"url": "images/module1/fils-continuite.jpg", "alt": "Les trois fils de la continuité : figure de sécurité de substitution, continuité relationnelle, continuité de l'environnement", "legende": "Trois fils à tisser : une figure de sécurité de substitution, des interactions prévisibles et chaleureuses, un cadre de vie stable."}$kk$::jsonb, 33),
  ('question', $kk${"enonce": "Lesquelles de ces pratiques contribuent à la continuité entre la maison et la crèche ? (plusieurs réponses)", "options": [{"texte": "Une période de familiarisation progressive", "juste": true}, {"texte": "Des transmissions de qualité avec les parents", "juste": true}, {"texte": "Le respect de l'objet transitionnel de l'enfant", "juste": true}, {"texte": "Changer régulièrement l'adulte de référence pour que l'enfant s'habitue à tous", "juste": false}], "explication": "La continuité repose sur des adultes **stables** et prévisibles, sur la familiarisation, les transmissions et l'objet transitionnel. Changer souvent d'adulte autour de l'enfant va à l'inverse de la sécurité."}$kk$::jsonb, 34),
  ('texte', $kk${"titre": "L'art du « prendre soin » : des gestes qui sécurisent", "paragraphes": ["La sécurité affective se construit dans les **détails du quotidien**. Chaque soin (change, repas, coucher) est une occasion de renforcer le lien et le sentiment de compétence de l'enfant. L'approche **Pikler-Lóczy** en donne quatre repères.", "**La verbalisation constante** : l'adulte dit toujours à l'enfant ce qu'il va faire avec lui. Prévenir, nommer, expliquer. **La qualité des gestes** : des gestes lents, respectueux, qui n'agressent pas le corps de l'enfant et sollicitent sa coopération. **L'attention et le regard** : l'observation est une forme de soin psychique, et le regard de l'adulte a une portée contenante. **La disponibilité physique et psychique** : être pleinement présent durant les temps individualisés (change, repas…)."]}$kk$::jsonb, 35),
  ('image', $kk${"url": "images/module1/prendre-soin.jpg", "alt": "Les mains d'un adulte qui habille un bébé allongé", "legende": "Le soin est un moment de relation : gestes lents, paroles, regard et présence."}$kk$::jsonb, 36),
  ('citation', $kk${"texte": "« La science et l'art du soin sont alors bien nécessaires. »\nMyriam David"}$kk$::jsonb, 37),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Une collègue vous dit : « Laisse-la pleurer »", "contexte": "10 h. Une enfant de 13 mois pleure depuis l'arrivée de son parent. Vous vous approchez pour la prendre dans vos bras. Une collègue, pressée, intervient.", "repliques": [{"qui": "Votre collègue", "texte": "Laisse-la pleurer, elle fait ça pour qu'on la prenne. Si tu la consoles à chaque fois, elle va prendre de mauvaises habitudes."}], "consigne": "Que répondez-vous à votre collègue ?", "reponse_modele": "Je comprends qu'on soit sous pression le matin. Mais à cet âge, elle ne peut pas encore se calmer seule : son cerveau est en construction. La consoler, ce n'est pas lui céder, c'est l'aider à apprendre à se réguler. Je m'en occupe et on en reparle à la pause, si tu veux.", "points": ["Parler de pratiques, pas de personnes : la bienveillance vaut aussi entre collègues.", "S'appuyer sur ce que l'on sait : le cerveau du jeune enfant est en construction, il a besoin d'un co-régulateur.", "Agir, puis proposer d'en reparler, plutôt que d'opposer deux positions sur le moment."]}$kk$::jsonb, 38),
  ('retenir', $kk${"titre": "À retenir", "points": ["**Accueillir, c'est d'abord séparer :** la séparation est une épreuve pour l'enfant et pour ses parents.", "**Un jeune enfant ne peut pas réguler seul ses émotions :** pleurs ou colère ne sont ni un caprice, ni une provocation. Il a besoin d'un adulte co-régulateur.", "**La sécurité vient avant l'exploration :** un enfant qui peut compter sur un adulte sensible ose s'éloigner.", "**Chaque enfant est à un endroit différent :** on observe pour adapter notre accompagnement, sans étiqueter.", "**Consoler n'est pas du laxisme :** la réaction de l'adulte construit, ou entrave, la régulation émotionnelle.", "**Accueillir l'enfant, c'est accueillir sa famille :** on tisse des fils de continuité entre la maison et la crèche."]}$kk$::jsonb, 39),
  ('essayer', $kk${"label": "À essayer cette semaine", "titre": "Une arrivée plus sûre", "etapes": [{"titre": "Observer.", "texte": "Lors d'une arrivée, regardez où va le regard de l'enfant et vers qui il se tourne."}, {"titre": "Dire ce que je fais.", "texte": "Avant chaque geste (le prendre, le déshabiller, le consoler), je lui dis ce que je vais faire avec lui."}, {"titre": "Accueillir le parent.", "texte": "Je lui dis un mot sur son enfant et sur ce que nous allons faire pour qu'il se sente en sécurité."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$::jsonb, 40),
  ('reflexion', $kk${"question": "Quel geste allez-vous essayer cette semaine, et dans quelle situation précise ?", "sous_titre": "Une phrase suffit. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 41),
  ('texte', $kk${"titre": "Pour aller plus loin", "paragraphes": ["Les repères de cette séquence s'appuient sur les travaux de **John Bowlby** et de **Mary Ainsworth** (attachement), de **D. W. Winnicott** (continuité d'être), de l'approche **Pikler-Lóczy** et de **Myriam David** (soin), ainsi que sur les écrits de **Miriam Rasse** et de **Martine Maurice**, et sur la **Charte nationale d'accueil du jeune enfant**.", "Dans la séquence suivante, vous verrez que l'enfant choisit ses figures d'attachement, et comment l'équipe s'organise pour qu'il en trouve au moins une qui soit stable : la **constellation d'attachement**."]}$kk$::jsonb, 42)
  ) as v(type, contenu, ordre);

  raise notice '26.2 : 43 blocs ajoutés';
end
$do$;
-- FIN 26.2

-- ---------------------------------------------------------------------------
-- 26c Contrôle (lecture seule). Attendu : 1 séquence, 43 blocs (12 texte, 11 image,
-- 6 question, 3 dialogue, 3 reflexion, 3 citation, 2 scenes, 1 comparaison,
-- 1 retenir, 1 essayer), publie = false, sans trame.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame is null) as sans_trame,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs,
       (select string_agg(x.type || ' ' || x.n, ', ' order by x.type)
          from (select b.type, count(*) as n from public.bloc b where b.module_id = m.id group by b.type) x) as repartition
from public.module m join public.theme t on t.id = m.theme_id
where t.nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$;
-- FIN 26c
